// Small autonomous punt and kickoff executor. Player decisions use only the
// declared unit, player ratings, and current ball/player state. Kick placement
// is generated by a bounded authored kick model; return spots and contacts
// come from the live simulation.
import { DT, FIELD_W, FIELD_W_YD, G, REC_HZ, YD } from '../constants.js';
import { rng } from '../rng.js';
import { AERO, solveLaunch } from '../ball.js';
import { Player, POSE, World } from '../world.js';
import { assertNoOutcomeFields } from './schema.js';
import { retroDecisionInterval } from './retro-cadence.js';
import { estimateBallLanding } from './perception.js';

// Long kickoff returns can cover the field diagonally while players disengage
// and reset their lanes. Keep a hard bound, but allow the generated live play
// to reach the returner's touchdown or the pursuit tackle.
const MAX_SECONDS = 36;
const MAX_PLAYERS_PER_SIDE = 11;
const clamp = (v, lo, hi) => Math.max(lo, Math.min(hi, v));
const dist = (a, b) => Math.hypot(a.x - b.x, a.y - b.y);
const unit = (x, y) => {
  const n = Math.hypot(x, y);
  return n > 1e-9 ? { x: x / n, y: y / n } : { x: 0, y: 0 };
};

const ARCH = {
  kicker: { mass: 91, height: 1.83, radius: 0.303, vmax: 8.7, f0: 980, drive: 620, alat: 8.0, reach: 3.1 },
  coverage: { mass: 99, height: 1.85, radius: 0.31, vmax: 9.1, f0: 1030, drive: 690, alat: 8.1, reach: 3.15 },
  returner: { mass: 96, height: 1.80, radius: 0.306, vmax: 9.3, f0: 1080, drive: 670, alat: 8.65, reach: 3.14 },
  blocker: { mass: 125, height: 1.92, radius: 0.335, vmax: 8.0, f0: 1160, drive: 930, alat: 6.4, reach: 3.2 },
};
const BASE = {
  kicker: { SPD: 60, ACC: 60, AGI: 60, STR: 55, AWR: 65, KPW: 70, KAC: 70, CTH: 50, CAR: 60 },
  coverage: { SPD: 72, ACC: 72, AGI: 70, STR: 66, AWR: 65, PUR: 68, TAK: 66, BSH: 60, RBK: 55, CTH: 50, CAR: 60 },
  returner: { SPD: 80, ACC: 80, AGI: 82, STR: 62, AWR: 68, PRC: 68, CTH: 75, CAR: 76, BCV: 75, ELU: 72, TRK: 62 },
  blocker: { SPD: 64, ACC: 63, AGI: 62, STR: 76, AWR: 64, RBK: 68, IBL: 68, CTH: 52, CAR: 60 },
};
const RATING_KEYS = new Set(['SPD', 'ACC', 'AGI', 'STR', 'AWR', 'PUR', 'TAK', 'BSH', 'RBK', 'IBL',
  'CTH', 'CAR', 'BCV', 'ELU', 'TRK', 'PRC', 'KPW', 'KAC']);
const ROLE_RATINGS = {
  kicker: ['SPD', 'ACC', 'AGI', 'STR', 'AWR', 'KPW', 'KAC'],
  coverage: ['SPD', 'ACC', 'AGI', 'STR', 'AWR', 'PUR', 'TAK', 'BSH', 'RBK'],
  returner: ['SPD', 'ACC', 'AGI', 'STR', 'AWR', 'CTH', 'CAR', 'BCV', 'ELU', 'TRK', 'PRC'],
  blocker: ['SPD', 'ACC', 'AGI', 'STR', 'AWR', 'RBK', 'IBL', 'CTH', 'CAR'],
};

function requireObject(value, label) {
  if (!value || typeof value !== 'object' || Array.isArray(value)) throw new TypeError(`${label} must be an object`);
  return value;
}

function validateInput(input) {
  requireObject(input, 'special-teams input');
  assertNoOutcomeFields(input);
  const allowed = new Set(['schema_version', 'kind', 'seed', 'kicking_team', 'receiving_team',
    'yardline_100', 'ball_lateral_yards', 'lineups', 'player_profiles']);
  for (const key of Object.keys(input)) if (!allowed.has(key)) throw new TypeError(`unsupported special-teams input: ${key}`);
  if (input.schema_version !== 'gridiron.autonomous-special-teams.v1') throw new TypeError('unsupported special-teams schema');
  if (!['punt', 'kickoff', 'field_goal'].includes(input.kind)) throw new RangeError('special-teams kind must be punt, kickoff, or field_goal');
  if (!(typeof input.seed === 'string' && input.seed.trim()) && !Number.isInteger(input.seed)) throw new TypeError('seed must be a non-empty string or integer');
  for (const key of ['kicking_team', 'receiving_team']) if (typeof input[key] !== 'string' || !input[key].trim()) throw new TypeError(`${key} must be a team identity`);
  if (input.kicking_team === input.receiving_team) throw new TypeError('special-teams units must belong to different teams');
  if (!Number.isInteger(input.yardline_100) || input.yardline_100 < 1 || input.yardline_100 > 99) throw new RangeError('yardline_100 must be an integer from 1 to 99');
  const lateral = input.ball_lateral_yards ?? FIELD_W_YD / 2;
  if (!Number.isFinite(lateral) || lateral < 1 || lateral > FIELD_W_YD - 1) throw new RangeError('ball_lateral_yards must be inside the field');
  const lineups = requireObject(input.lineups, 'lineups');
  const kicking = requireObject(lineups.kicking, 'lineups.kicking');
  const receiving = requireObject(lineups.receiving, 'lineups.receiving');
  const specialist = input.kind === 'punt' ? kicking.punter : kicking.kicker;
  if (typeof specialist !== 'string' || !specialist.trim()) throw new TypeError(`lineups.kicking.${input.kind === 'punt' ? 'punter' : 'kicker'} is required`);
  if (!Array.isArray(kicking.coverage) || kicking.coverage.length !== 10 || kicking.coverage.some((id) => typeof id !== 'string' || !id.trim())) throw new TypeError('kicking coverage must name ten players');
  if (typeof receiving.returner !== 'string' || !receiving.returner.trim()) throw new TypeError('receiving returner is required');
  if (!Array.isArray(receiving.blockers) || receiving.blockers.length !== 10 || receiving.blockers.some((id) => typeof id !== 'string' || !id.trim())) throw new TypeError('receiving blockers must name ten players');
  const ids = [specialist, ...kicking.coverage, receiving.returner, ...receiving.blockers];
  if (new Set(ids).size !== 22) throw new TypeError('special-teams lineups must contain 22 unique player ids');
  const profiles = requireObject(input.player_profiles, 'player_profiles');
  for (const id of ids) {
    const profile = requireObject(profiles[id], `player_profiles.${id}`);
    const role = id === specialist ? 'kicker'
      : id === lineups.receiving.returner ? 'returner'
        : lineups.kicking.coverage.includes(id) ? 'coverage' : 'blocker';
    const ratings = requireObject(profile.ratings, `player_profiles.${id}.ratings`);
    for (const [name, value] of Object.entries(ratings)) {
      if (!RATING_KEYS.has(name)) throw new TypeError(`unsupported special-teams rating ${name}`);
      if (!Number.isFinite(value) || value < 1 || value > 99) throw new RangeError(`${id}.${name} must be from 1 to 99`);
    }
    for (const name of ROLE_RATINGS[role]) if (ratings[name] == null) {
      throw new TypeError(`${id}.ratings_missing:${name}`);
    }
    if (profile.physics?.mass != null && (!Number.isFinite(profile.physics.mass) || profile.physics.mass < 50 || profile.physics.mass > 200)) {
      throw new RangeError(`${id}.physics.mass must be from 50 to 200 kg`);
    }
  }
  return { ...input, seed: String(input.seed), ball_lateral_yards: lateral, lineups, profiles };
}

function infoFor(id, role, profiles) {
  const archetype = role === 'specialist' ? 'kicker' : role === 'returner' ? 'returner' : role === 'coverage' ? 'coverage' : 'blocker';
  const base = ARCH[archetype];
  const ratings = { ...BASE[archetype], ...(profiles[id].ratings ?? {}) };
  const physics = {
    ...base,
    mass: profiles[id].physics?.mass ?? base.mass,
    vmax: base.vmax * (0.84 + 0.0032 * (ratings.SPD ?? 60)),
    f0: base.f0 * (0.80 + 0.0040 * (ratings.ACC ?? 60)),
    drive: base.drive * (0.78 + 0.0044 * (ratings.STR ?? 60)),
    alat: base.alat * (0.82 + 0.0036 * (ratings.AGI ?? 60)),
  };
  return { id, ratings, physics };
}

function skill(rating) { return 0.75 + 0.5 * ((rating ?? 60) - 50) / 50; }

/** Simulate one punt or kickoff from the live kick through the return whistle. */
export function simulateAutonomousSpecialTeams(input) {
  const cfg = validateInput(input);
  if (cfg.kind === 'field_goal') return simulateAutonomousFieldGoal(cfg);
  const rand = rng(cfg.seed);
  const W = new World(rand);
  const lineups = cfg.lineups;
  const kickRoster = [];
  const returnRoster = [];
  const byId = new Map();
  const roster = [];
  const ballY = cfg.ball_lateral_yards * YD;
  const yFor = (index, total = 10) => clamp((FIELD_W_YD * (index + 0.5)) / total, 2, FIELD_W_YD - 2) * YD;
  const kickoff = cfg.kind === 'kickoff';
  const kickSpotY100 = cfg.yardline_100;
  const los = 100 - kickSpotY100;
  const specialistId = kickoff ? lineups.kicking.kicker : lineups.kicking.punter;
  const assignments = new Map();
  const addPlayer = (id, team, role, position, assignment, index) => {
    const info = infoFor(id, role, cfg.profiles);
    const p = W.add(new Player(info, team, role));
    p.p = { x: position.x * YD, y: position.y * YD };
    p.h = team === 'K' ? 0 : Math.PI;
    p.ai.assignment = assignment;
    p.ai.decision = 'read live kick and unit assignment';
    p.ai.nextDecision = 0;
    p.ai.role = role;
    p.ai.index = index;
    p.ai.nextShed = null;
    p.engageMul = skill(p.R.RBK ?? p.R.IBL ?? p.R.BSH ?? 60) * (0.8 + 0.2 * (p.R.STR ?? 60) / 80);
    p.pose = role === 'blocker' ? POSE.STANCE : POSE.RUN;
    p.roleKey = `${team}.${role}${index == null ? '' : index + 1}`;
    p.ai.assignment = assignment;
    assignments.set(id, assignment);
    byId.set(id, p);
    roster.push({ id, team, slot: p.roleKey, roleKey: p.roleKey });
    W.event('assignment_executed', { player_id: id, role: p.roleKey, task: assignment });
    (team === 'K' ? kickRoster : returnRoster).push(p);
    return p;
  };

  const specialistX = kickoff ? los : Math.max(2, los - 12);
  const specialist = addPlayer(specialistId, 'K', 'specialist', { x: specialistX, y: ballY / YD },
    kickoff ? 'kickoff and cover' : 'receive snap, punt downfield, then cover', null);
  lineups.kicking.coverage.forEach((id, i) => {
    const x = kickoff ? los + 5 : los - (i === 4 ? 0.3 : 0.8);
    const p = addPlayer(id, 'K', 'coverage', { x, y: yFor(i) / YD }, `cover lane ${i + 1}; pursue current returner`, i);
    p.ai.lane = i;
  });
  const returnStartX = kickoff ? 91 : clamp(los + 28, 12, 94);
  const returner = addPlayer(lineups.receiving.returner, 'R', 'returner',
    { x: returnStartX, y: ballY / YD }, 'track the live kick; catch or return through daylight', null);
  lineups.receiving.blockers.forEach((id, i) => {
    const row = Math.floor(i / 5), col = i % 5;
    const x = kickoff ? 18 + row * 5 : clamp(los + 10 + row * 5, 8, 92);
    const y = clamp((col - 2) * 3.2 + (row ? 1.4 : -1.4), -24, 24) + ballY / YD;
    addPlayer(id, 'R', 'blocker', { x, y: clamp(y, 1.5, FIELD_W_YD - 1.5) },
      `form return wall; block nearest live coverage threat`, i);
  });

  const frames = [];
  let nextFrame = 0;
  const stride = roster.length * 6 + 6;
  const record = () => {
    const frame = new Float32Array(stride);
    let n = 0;
    for (const p of W.players) {
      frame[n++] = p.p.x / YD; frame[n++] = p.p.y / YD; frame[n++] = p.h;
      frame[n++] = p.speed / YD; frame[n++] = p.down ? POSE.DOWN : p.pose; frame[n++] = p.hasBall ? 1 : 0;
    }
    const ball = W.ball;
    frame[n++] = ball.x / YD; frame[n++] = ball.y / YD; frame[n++] = ball.z;
    frame[n++] = ball.spin; frame[n++] = ball.rot; frame[n++] = 0;
    frames.push(frame);
  };
  const setIntent = (p, assignment, decision) => {
    if (p.ai.assignment === assignment && p.ai.decision === decision) return;
    p.ai.assignment = assignment;
    p.ai.decision = decision;
    W.event('decision', { player_id: p.id, role: p.roleKey, assignment, decision });
  };
  const seek = (p, target, fraction = 1, decel = 7) => {
    const dx = target.x - p.p.x, dy = target.y - p.p.y;
    const d = Math.hypot(dx, dy);
    if (d < 0.05) return { x: 0, y: 0 };
    const speed = Math.min(p.vmax * fraction, Math.sqrt(2 * decel * d));
    return { x: dx / d * speed, y: dy / d * speed };
  };
  const nearest = (from, list, filter = () => true) => list.filter(filter).sort((a, b) => dist(a.p, from.p) - dist(b.p, from.p) || a.id.localeCompare(b.id))[0] ?? null;
  const catchSkill = clamp(0.64 + ((returner.R.CTH ?? 70) - 70) * 0.007 + ((returner.R.AWR ?? 65) - 65) * 0.0025, 0.18, 0.96);

  // The flight target is private to the ball model. Returners steer toward
  // observed ball coordinates, never toward this generated landing point.
  const strength = clamp(specialist.R.KPW ?? 70, 1, 99);
  const safetyFreeKick = kickoff && kickSpotY100 === 80;
  const distanceYards = kickoff
    ? safetyFreeKick
      ? clamp(72 + (strength - 70) * 0.24 + rand.normal() * 3.6, 55, 90)
      : clamp(59 + (strength - 70) * 0.24 + rand.normal() * 3.6, 45, 76)
    : clamp(41 + (strength - 70) * 0.28 + rand.normal() * 2.8, 28, 62);
  const accuracy = clamp(specialist.R.KAC ?? 70, 1, 99);
  const kickX = kickoff ? los : specialistX + 1.2;
  const landingX = kickX + distanceYards;
  const hang = clamp((kickoff ? 3.6 : 3.7) + distanceYards * 0.012, 3.6, 4.8);
  const lateralSigma = (kickoff ? 1.1 : 1.8) * (1.45 - (accuracy - 1) * (0.9 / 98));
  const lateralOffset = clamp(rand.normal() * lateralSigma, -4, 4);
  const launchFrom = { x: kickX * YD, y: ballY, z: 0.85 };
  const launchTo = { x: landingX * YD, y: (ballY / YD + lateralOffset) * YD, z: 0.12 };
  const flight = solveLaunch(launchFrom, launchTo, hang, AERO.wobble);
  Object.assign(W.ball, { state: 'air', holder: null, x: launchFrom.x, y: launchFrom.y,
    z: launchFrom.z, vx: flight.vx, vy: flight.vy, vz: flight.vz, k: flight.k, tumble: true });
  W.event('kick', { by: specialist.id, kind: cfg.kind, distance_yards: Math.round(distanceYards), hang_seconds: hang });
  specialist.pose = POSE.KICK;

  let carrier = null;
  let returnStartXActual = null;
  let returnStartYActual = null;
  let muffed = false;
  let recovery = null;
  let terminal = null;
  let tackleStarted = null;
  let catchResolved = false;
  let catchAt = null;
  let fairCaught = false;
  let carrierDecision = 0;
  let selectedLaneY = null;
  let deadBall = null;
  let deadReason = null;
  const decisionCount = new Map(W.players.map((p) => [p.id, 0]));

  function attemptRecovery() {
    if (W.ball.state !== 'loose') return;
    const candidates = [...W.players].filter((p) => !p.down && dist(p.p, { x: W.ball.x, y: W.ball.y }) < 1.15)
      .sort((a, b) => dist(a.p, { x: W.ball.x, y: W.ball.y }) - dist(b.p, { x: W.ball.x, y: W.ball.y }) || a.id.localeCompare(b.id));
    const p = candidates[0];
    if (!p || rand() > clamp(0.55 + ((p.R.AWR ?? 60) - 60) * 0.004, 0.25, 0.9)) return;
    recovery = p;
    carrier = p;
    p.hasBall = true;
    p.mode = 'carry';
    W.ball.state = 'held'; W.ball.holder = p; W.ball.hand = 'carry';
    W.event('kick_recovery', { player_id: p.id, team: p.team, muff: muffed });
    // A muff recovery is whistled at the recovery spot in this V1 contract;
    // return after recovery requires a separate classified event transition.
    if (muffed) {
      deadBall = { x: W.ball.x / YD, y: W.ball.y / YD };
      deadReason = 'muff_recovery';
      terminal = W.t;
    }
  }

  function observeBall(p) {
    const b = W.ball;
    if (b.state === 'air') {
      const landing = estimateBallLanding({ position: { x: b.x, y: b.y },
        velocity: { x: b.vx, y: b.vy }, z: b.z, vz: b.vz, uncertaintyMeters: 0 }, G);
      return seek(p, { x: landing.x, y: landing.y }, 0.9, 8);
    }
    if (b.state === 'loose') return seek(p, { x: b.x, y: b.y }, 0.88);
    return seek(p, p.p, 0);
  }

  function chooseReturnLane(p) {
    const threats = kickRoster.filter((q) => !q.down && q !== specialist);
    const candidates = [-8, -4, 0, 4, 8].map((offset) => {
      const y = clamp(p.p.y / YD + offset, 1.5, FIELD_W_YD - 1.5) * YD;
      const ahead = threats.filter((q) => q.p.x < p.p.x + 2 * YD);
      const space = ahead.reduce((score, q) => {
        const forward = Math.max(0, p.p.x - q.p.x) / YD;
        const lateral = Math.abs(y - q.p.y) / YD;
        return score + 1 / (1 + forward * 0.08 + lateral * 0.45);
      }, 0);
      return { y, score: space + rand() * 0.025 };
    });
    candidates.sort((a, b) => a.score - b.score || a.y - b.y);
    selectedLaneY = candidates[0].y;
  }

  function brain(p) {
    const interval = retroDecisionInterval(clamp(p.R.AWR ?? 60, 1, 99));
    const stateChanged = p.ai.lastBallState !== W.ball.state || p.ai.lastCarrier !== (carrier?.id ?? null);
    if (!stateChanged && W.t + 1e-9 < p.ai.nextDecision) return;
    p.ai.nextDecision = W.t + interval;
    p.ai.lastBallState = W.ball.state;
    p.ai.lastCarrier = carrier?.id ?? null;
    decisionCount.set(p.id, decisionCount.get(p.id) + 1);
    if (p.team === 'K' && p.engaged && carrier?.team === 'R') {
      const engagement = W.engagements.find((row) => row.a === p || row.b === p);
      if (engagement && (p.ai.nextShed == null || W.t >= p.ai.nextShed)) {
        setIntent(p, 'shed return block', 'use strength and block-shed skill to rejoin coverage pursuit');
        W.disengage(engagement, p);
        p.ai.nextShed = W.t + clamp(1.25 - ((p.R.BSH ?? 60) - 50) * 0.009, 0.45, 1.7);
      }
    }
    const ball = { x: W.ball.x, y: W.ball.y };
    if (p === specialist) {
      p.dv = carrier && carrier.team === 'R' ? seek(p, carrier.p, 0.95) : seek(p, p.p, 0);
      return;
    }
    if (p.team === 'K') {
      if (carrier?.team === 'R') {
        const target = { x: carrier.p.x + carrier.v.x * 0.16, y: carrier.p.y + carrier.v.y * 0.16 };
        setIntent(p, 'coverage pursuit', 'close on the current returner and attempt a wrap');
        p.dv = seek(p, target);
      } else if (W.ball.state === 'air' || W.ball.state === 'loose') {
        const laneY = clamp(ball.y + (p.ai.lane - 4.5) * 0.42 * YD, 1.5 * YD, (FIELD_W_YD - 1.5) * YD);
        setIntent(p, `cover lane ${p.ai.lane + 1}`, 'read current ball flight, then close the return lane');
        p.dv = seek(p, { x: ball.x + (cfg.kind === 'punt' ? 4 : 2) * YD, y: laneY }, 0.96);
      } else p.dv = seek(p, p.p, 0);
      return;
    }
    if (p === returner) {
      if (!carrier) {
        setIntent(p, 'track and secure the live kick', 'adjust to observed ball position and catch when in reach');
        p.dv = observeBall(p);
      } else if (carrier === p) {
        if (W.t >= carrierDecision) {
          chooseReturnLane(p);
          carrierDecision = W.t + Math.max(0.4, interval * 3);
          setIntent(p, 'return through daylight', 'scan current coverage and select the clearest observed lane');
        }
        const targetX = Math.max(0.5, p.p.x / YD - 3.0) * YD;
        p.dv = seek(p, { x: targetX, y: selectedLaneY ?? p.p.y }, 1, 5.6);
      } else p.dv = seek(p, p.p, 0);
      return;
    }
    if (p.role === 'blocker') {
      if (carrier?.team === 'R') {
        const threat = p.ai.index < 6
          ? nearest(p, kickRoster.filter((q) => q !== specialist), (q) => !q.down && !q.engaged && q.p.x < carrier.p.x + 5 * YD)
          : null;
        if (threat) {
          setIntent(p, 'engage nearest coverage threat', 'protect the current return lane');
          p.dv = seek(p, { x: threat.p.x + 0.55 * YD, y: threat.p.y }, 0.9, 4.5);
          if (dist(p.p, threat.p) <= p.r + threat.r + 0.16 * YD) W.engage(p, threat);
        } else {
          const offset = ((p.ai.index % 5) - 2) * 1.2 * YD;
          setIntent(p, 'escort returner', 'stay ahead of the ball carrier and preserve the lane');
          p.dv = seek(p, { x: carrier.p.x - 2.0 * YD, y: clamp(carrier.p.y + offset, 1.5 * YD, (FIELD_W_YD - 1.5) * YD) }, 0.8);
        }
      } else if (!carrier && (W.ball.state === 'air' || W.ball.state === 'loose')) {
        const threat = nearest(p, kickRoster, (q) => !q.down && !q.engaged);
        if (threat && dist(p.p, threat.p) < 6 * YD) {
          setIntent(p, 'protect the catch point', 'engage the nearest coverage player');
          p.dv = seek(p, threat.p, 0.8);
          if (dist(p.p, threat.p) <= p.r + threat.r + 0.16 * YD) W.engage(p, threat);
        } else p.dv = seek(p, { x: returner.p.x - 2 * YD, y: returner.p.y }, 0.6);
      } else p.dv = seek(p, p.p, 0);
      return;
    }
  }

  for (let step = 0; step < Math.ceil(MAX_SECONDS / DT); step++) {
    if (terminal != null) break;
    W.step(DT, brain);
    if (!catchResolved && W.ball.state === 'air' && W.ball.z <= 2.4) {
      const d = Math.hypot(W.ball.x - returner.p.x, W.ball.y - returner.p.y);
      if (d <= 1.35 * YD) {
        catchResolved = true;
        catchAt = W.t;
        if (rand() <= catchSkill) {
          carrier = returner; returner.hasBall = true; returner.mode = 'carry';
          W.ball.state = 'held'; W.ball.holder = returner; W.ball.hand = 'carry';
          returnStartXActual = returner.p.x / YD; returnStartYActual = returner.p.y / YD;
          W.event('catch', { player_id: returner.id, ball_spot: { x: returnStartXActual, y: returnStartYActual } });
          if (!kickoff) {
            const nearestThreat = Math.min(...kickRoster.filter((p) => p !== specialist && !p.down)
              .map((p) => dist(p.p, returner.p)));
            const fairCatchSkill = clamp(0.35 + ((returner.R.AWR ?? 65) - 65) * 0.008, 0.12, 0.82);
            if (nearestThreat <= 5.5 * YD && rand() < fairCatchSkill) {
              fairCaught = true;
              deadBall = { x: returnStartXActual, y: returnStartYActual };
              deadReason = 'fair_catch'; terminal = W.t;
              W.event('fair_catch', { player_id: returner.id, ball_spot: deadBall });
            }
          }
          if (kickoff && returnStartXActual >= 100) {
            deadBall = { x: 100, y: returnStartYActual }; deadReason = 'touchback'; terminal = W.t;
          }
        } else {
          muffed = true;
          W.ball.state = 'loose'; W.ball.holder = null;
          returner.hasBall = false;
          W.event('muff', { player_id: returner.id, ball_spot: { x: W.ball.x / YD, y: W.ball.y / YD } });
        }
      }
    }
    if (W.ball.state === 'loose' && muffed && recovery == null) attemptRecovery();
    if (terminal == null && W.ball.state === 'air' && (W.ball.y < 0 || W.ball.y > FIELD_W)) {
      deadBall = { x: clamp(W.ball.x / YD, 0, 100), y: clamp(W.ball.y / YD, 0, FIELD_W_YD) };
      deadReason = 'out_of_bounds'; terminal = W.t;
      W.event('kick_out_of_bounds', { ball_spot: deadBall });
    }
    if (terminal == null && W.ball.state === 'air' && W.ball.x >= 100 * YD) {
      deadBall = { x: 100, y: W.ball.y / YD }; deadReason = 'touchback'; terminal = W.t;
    }
    if (W.ball.state === 'loose' && !muffed && W.ball.z <= 0.11) {
      // A ball that is not fielded is downed where the live ball settles.
      deadBall = { x: clamp(W.ball.x / YD, 0, 100), y: clamp(W.ball.y / YD, 0, FIELD_W_YD) };
      deadReason = 'downed'; terminal = W.t;
    }
    if (terminal == null && carrier === returner) {
      const tackler = kickRoster.filter((p) => !p.down && !p.engaged)
        .sort((a, b) => dist(a.p, returner.p) - dist(b.p, returner.p) || a.id.localeCompare(b.id))[0];
      const tackleReach = 0.35 + ((tackler?.R.TAK ?? 60) - 50) * 0.003;
      if (tackleStarted == null && tackler && dist(tackler.p, returner.p) <= tackler.r + returner.r + tackleReach * YD) {
        W.wrap(tackler, returner, { fall: 0.28, keepCarrier: 0.28 });
        tackleStarted = W.t;
        W.event('return_tackle', { tackler_id: tackler.id, returner_id: returner.id });
      }
      if (returner.p.x <= 0.55 * YD) {
        deadBall = { x: 0, y: clamp(returner.p.y / YD, 0, FIELD_W_YD) };
        deadReason = 'touchdown'; terminal = W.t;
        W.event('touchdown', { player_id: returner.id, team: 'R' });
      } else if (returner.p.y < 0 || returner.p.y > FIELD_W) {
        deadBall = { x: clamp(returner.p.x / YD, 0, 100), y: clamp(returner.p.y / YD, 0, FIELD_W_YD) };
        deadReason = 'out_of_bounds'; terminal = W.t;
      } else if (tackleStarted != null && W.t - tackleStarted >= 0.3) {
        deadBall = { x: clamp(returner.p.x / YD, 0, 100), y: clamp(returner.p.y / YD, 0, FIELD_W_YD) };
        deadReason = 'tackle'; terminal = W.t;
      }
    }
    if (terminal == null && W.t >= nextFrame - 1e-9) {
      record(); nextFrame += 1 / REC_HZ;
    }
  }
  if (terminal == null) {
    if (muffed && recovery) {
      deadBall = { x: recovery.p.x / YD, y: recovery.p.y / YD };
      deadReason = 'muff_recovery'; terminal = W.t;
    } else {
      return { schema_version: 'gridiron.autonomous-special-teams.v1', status: 'failed', kind: cfg.kind,
        failure: { reason: 'special_teams_live_ball_time_cap', time_limit_seconds: MAX_SECONDS }, events: W.events,
        trajectory: { roster, frames: frames.map((frame) => Array.from(frame)), stride, t0: 0, hz: REC_HZ },
        diagnostics: { assignments_executed: assignments.size, expected_assignments: 22,
          decision_counts: Object.fromEntries(decisionCount), outcome_inputs: [],
          player_execution: W.players.map((p) => ({ player_id: p.id, assignment: assignments.get(p.id),
            x_yards: p.p.x / YD, y_yards: p.p.y / YD, speed_yards_per_second: p.speed / YD })) } };
    }
  }
  if (frames.length === 0 || terminal - (frames.length - 1) / REC_HZ > 1e-6) record();

  let result;
  if (deadReason === 'touchback') {
    result = { result: 'touchback', possession_after: 'receiving_team',
      kick_spot_yardline_100: kickSpotY100, distance_yards: Math.round(distanceYards),
      dead_ball_yardline_100: kickoff ? (kickSpotY100 === 80 ? 20 : 35) : 20,
      return_yards: null, returner_id: null };
  } else if (deadReason === 'muff_recovery') {
    const team = recovery?.team === 'K' ? 'kicking_team' : 'receiving_team';
    const fumbleSpot = Math.round(100 - (W.events.find((e) => e.type === 'muff')?.ball_spot?.x ?? deadBall.x));
    const recoverySpot = Math.round(100 - deadBall.x);
    result = { result: 'muff', possession_after: team, recovery_team: team,
      kick_spot_yardline_100: kickSpotY100, distance_yards: Math.round(distanceYards),
      dead_ball_yardline_100: recoverySpot, recovery_yardline_100: recoverySpot,
      fumble_spot_yardline_100: fumbleSpot, receiving_team_touched_beyond_line: true,
      return_yards: null, returner_id: returner.id, recoverer_id: recovery?.id ?? null };
  } else if (deadReason === 'fair_catch') {
    const spot = Math.round(100 - deadBall.x);
    result = { result: 'fair_catch', possession_after: 'receiving_team',
      kick_spot_yardline_100: kickSpotY100, distance_yards: Math.round(distanceYards),
      return_start_yardline_100: spot, dead_ball_yardline_100: spot,
      return_yards: null, returner_id: returner.id, fair_catch: true };
  } else if (deadReason === 'downed' || deadReason === 'out_of_bounds') {
    result = { result: deadReason, possession_after: 'receiving_team',
      kick_spot_yardline_100: kickSpotY100, distance_yards: Math.round(distanceYards),
      dead_ball_yardline_100: Math.round(100 - deadBall.x), return_yards: null,
      returner_id: null, out_of_bounds: deadReason === 'out_of_bounds' };
  } else {
    const startX = returnStartXActual ?? clamp(landingX, 1, 99);
    const startSpot = Math.round(100 - startX);
    const deadSpot = Math.round(100 - deadBall.x);
    const returnYards = deadSpot - startSpot;
    result = { result: 'return', possession_after: 'receiving_team',
      kick_spot_yardline_100: kickSpotY100, distance_yards: Math.round(distanceYards),
      return_start_yardline_100: Math.round(startSpot), dead_ball_yardline_100: Math.round(deadSpot),
      return_yards: returnYards, returner_id: returner.id,
      scoring: deadReason === 'touchdown' ? 'touchdown' : null,
      fair_catch: false, out_of_bounds: false };
  }
  result.elapsed_seconds = terminal;
  result.catch_elapsed_seconds = catchAt;
  // The game clock starts on a legal receiving-team touch and stops at the
  // whistle. Flight time before that touch and dead-ball time before the next
  // snap are not charged here; the game lifecycle owns any later restart.
  result.live_elapsed_seconds = (deadReason === 'touchback' || catchAt == null)
    ? 0 : Math.max(0, terminal - catchAt);
  result.clock_runoff_seconds = Math.ceil(result.live_elapsed_seconds);
  W.event('whistle', { reason: deadReason, ball_spot: deadBall, terminal_t: terminal });
  const framesFlat = frames.map((frame) => Array.from(frame));
  const resultRecord = {
    schema_version: 'gridiron.autonomous-special-teams.v1', status: 'complete', kind: cfg.kind,
    seed: cfg.seed, kicking_team: cfg.kicking_team, receiving_team: cfg.receiving_team,
    result, carrier_id: carrier?.id ?? null, events: W.events,
    trajectory: { roster, frames: framesFlat, stride, t0: 0, hz: REC_HZ },
    diagnostics: { assignments_executed: assignments.size, expected_assignments: 22,
      decision_counts: Object.fromEntries(decisionCount), outcome_inputs: [],
      player_execution: W.players.map((p) => ({ player_id: p.id, assignment: assignments.get(p.id),
        top_speed_yards_per_second: p.topSpeed / YD, distance_yards: p.dist / YD })),
      kick_model: { power_rating: strength, accuracy_rating: accuracy,
        generated_distance_yards: Math.round(distanceYards), lateral_sigma_yards: lateralSigma },
      provenance: 'generated kick placement and live bounded player execution' },
  };
  return resultRecord;
}

function simulateAutonomousFieldGoal(cfg) {
  const rand = rng(cfg.seed);
  const W = new World(rand);
  const { kicking, receiving } = cfg.lineups;
  const ballY = cfg.ball_lateral_yards * YD;
  const los = 100 - cfg.yardline_100;
  const center = FIELD_W / 2;
  const assignments = new Map();
  const roster = [];
  const seekPlayer = (p, target, fraction = 1, decel = 7) => {
    const dx = target.x - p.p.x, dy = target.y - p.p.y;
    const d = Math.hypot(dx, dy);
    if (d < 0.05) return { x: 0, y: 0 };
    const speed = Math.min(p.vmax * fraction, Math.sqrt(2 * decel * d));
    return { x: dx / d * speed, y: dy / d * speed };
  };
  const nearestPlayer = (from, list) => list.filter((p) => !p.down)
    .sort((a, b) => dist(a.p, from.p) - dist(b.p, from.p) || a.id.localeCompare(b.id))[0] ?? null;
  const add = (id, team, role, x, y, task, index = null) => {
    const archetype = role === 'specialist' ? 'kicker' : role;
    const p = W.add(new Player(infoFor(id, archetype, cfg.profiles), team, role));
    p.p = { x: x * YD, y };
    p.h = team === 'K' ? 0 : Math.PI;
    p.ai.assignment = task;
    p.ai.decision = 'execute assigned field-goal responsibility';
    p.ai.nextDecision = 0;
    p.ai.index = index;
    p.ai.role = role;
    p.roleKey = `${team}.${role}${index == null ? '' : index + 1}`;
    p.engageMul = skill(p.R.RBK ?? p.R.IBL ?? p.R.BSH ?? 60)
      * (0.8 + 0.2 * (p.R.STR ?? 60) / 80);
    assignments.set(id, task);
    roster.push({ id, team, slot: p.roleKey, roleKey: p.roleKey });
    W.event('assignment_executed', { player_id: id, role: p.roleKey, task });
    return p;
  };
  const kicker = add(kicking.kicker, 'K', 'specialist', los - 10, ballY,
    'approach the placed ball and kick through the upright window');
  const snapper = add(kicking.coverage[0], 'K', 'blocker', los, ballY,
    'long snap to the holder');
  const holder = add(kicking.coverage[1], 'K', 'blocker', los - 7, ballY,
    'receive the snap and place the ball');
  const protectors = kicking.coverage.slice(2).map((id, i) => {
    const y = center + ((i - 3.5) * 0.85 * YD);
    return add(id, 'K', 'blocker', los - 0.7, y,
      'protect the kicker and hold the kick lane', i);
  });
  const rushers = [receiving.returner, ...receiving.blockers].map((id, i) => {
    const y = center + ((i - 5) * 0.8 * YD);
    return add(id, 'R', i === 0 ? 'returner' : 'coverage', los + 0.45, y,
      'rush the assigned gap and attempt to block the kick', i);
  });

  const frames = [];
  const stride = roster.length * 6 + 6;
  const record = () => {
    const frame = new Float32Array(stride);
    let n = 0;
    for (const p of W.players) {
      frame[n++] = p.p.x / YD; frame[n++] = p.p.y / YD; frame[n++] = p.h;
      frame[n++] = p.speed / YD; frame[n++] = p.down ? POSE.DOWN : p.pose; frame[n++] = p.hasBall ? 1 : 0;
    }
    const b = W.ball;
    frame[n++] = b.x / YD; frame[n++] = b.y / YD; frame[n++] = b.z;
    frame[n++] = b.spin; frame[n++] = b.rot; frame[n++] = 0;
    frames.push(frame);
  };
  const snapAt = 0.08;
  const kickAt = 1.05;
  const goalpostX = 110 * YD;
  const distanceYards = cfg.yardline_100 + 17;
  const kickPower = clamp(kicker.R.KPW ?? 70, 1, 99);
  const kickAccuracy = clamp(kicker.R.KAC ?? 70, 1, 99);
  const accuracyScale = clamp(1.5 - kickAccuracy * 0.01, 0.45, 1.5);
  const horizontalSigma = (0.7 + distanceYards * 0.018) * accuracyScale;
  const verticalSigma = (0.65 + distanceYards * 0.01) * accuracyScale;
  const target = {
    x: goalpostX,
    y: ballY + rand.normal() * horizontalSigma,
    z: 3.75 + rand.normal() * verticalSigma,
  };
  let snapCaught = false;
  let snapStarted = false;
  let kickLaunched = false;
  let blocked = false;
  let resultName = null;
  let terminal = null;
  let crossing = null;
  let nextFrame = 0;
  let previousBall = null;
  let kickModel = null;

  W.ball.state = 'held';
  W.ball.holder = snapper;
  W.ball.hand = 'chest';
  snapper.hasBall = true;

  function setIntent(p, assignment, decision) {
    if (p.ai.assignment === assignment && p.ai.decision === decision) return;
    p.ai.assignment = assignment;
    p.ai.decision = decision;
    W.event('decision', { player_id: p.id, role: p.roleKey, assignment, decision });
  }

  function brain(p) {
    if (p === kicker || p === holder || p === snapper) {
      p.dv = p === kicker && snapCaught && !kickLaunched
        ? seekPlayer(p, W.ball, 0.8, 8) : seekPlayer(p, p.p, 0);
      return;
    }
    if (p.team === 'K') {
      const threat = nearestPlayer(p, rushers.filter((q) => !q.engaged));
      if (threat) {
        setIntent(p, 'engage the assigned protection gap', 'meet the nearest rusher and preserve the kick lane');
        p.dv = seekPlayer(p, { x: threat.p.x - 0.5 * YD, y: threat.p.y }, 0.72, 4.5);
        if (dist(p.p, threat.p) <= p.r + threat.r + 0.16 * YD) W.engage(p, threat);
      }
      return;
    }
    const protector = nearestPlayer(p, protectors.filter((q) => !q.engaged));
    const laneY = p.ai.index == null ? center : center + ((p.ai.index - 5) * 0.8 * YD);
    const targetPoint = protector ? { x: protector.p.x + 0.25 * YD, y: protector.p.y }
      : { x: los - 7.5, y: laneY };
    setIntent(p, 'rush the assigned gap', 'close on the protection and affect the kick');
    p.dv = seekPlayer(p, targetPoint, 0.88, 5.2);
    if (protector && dist(p.p, protector.p) <= p.r + protector.r + 0.16 * YD) W.engage(p, protector);
  }

  for (let step = 0; step < Math.ceil(7 / DT); step++) {
    if (terminal != null) break;
    if (!snapStarted && W.t >= snapAt) {
      snapStarted = true;
      const from = { x: W.ball.x, y: W.ball.y, z: 0.85 };
      const to = { x: holder.p.x, y: holder.p.y, z: 0.82 };
      const snap = solveLaunch(from, to, 0.32, AERO.spiral);
      snapper.hasBall = false;
      Object.assign(W.ball, { state: 'snap', holder: null, x: from.x, y: from.y, z: from.z,
        vx: snap.vx, vy: snap.vy, vz: snap.vz, k: snap.k });
      W.event('long_snap', { snapper_id: snapper.id, holder_id: holder.id });
    }
    const prior = { x: W.ball.x, y: W.ball.y, z: W.ball.z };
    W.step(DT, brain);

    if (!snapCaught && W.t >= snapAt) {
      const d = dist(W.ball, holder.p);
      if (d <= holder.r + 0.55 * YD) {
        snapCaught = true;
        snapper.hasBall = false;
        holder.hasBall = true;
        holder.mode = 'hold';
        W.ball.state = 'held'; W.ball.holder = holder; W.ball.hand = 'chest';
        W.event('snap_catch', { snapper_id: snapper.id, holder_id: holder.id });
      } else if (W.t > 0.5) {
        resultName = 'missed'; terminal = W.t;
        W.event('snap_failed', { snapper_id: snapper.id, holder_id: holder.id });
      }
    }

    if (snapCaught && !kickLaunched && W.t >= kickAt) {
      const pressure = rushers.some((r) => !r.down
        && dist(r.p, holder.p) <= r.r + holder.r + 0.30 * YD);
      if (pressure) {
        blocked = true;
        resultName = 'blocked';
        terminal = W.t;
        W.ball.state = 'loose'; W.ball.holder = null; holder.hasBall = false;
        W.event('kick_blocked', { blocker_id: nearest(holder, rushers, () => true)?.id ?? null,
          ball_spot: { x: W.ball.x / YD, y: W.ball.y / YD } });
      } else {
        kickLaunched = true;
        const from = { x: W.ball.x, y: W.ball.y, z: 0.55 };
        const distanceMeters = Math.max(1, goalpostX - from.x);
        const flightSeconds = clamp(0.95 + distanceMeters / 25, 1.4, 3.8);
        const flight = solveLaunch(from, target, flightSeconds, AERO.tumble);
        const speed = Math.hypot(flight.vx, flight.vy, flight.vz);
        const powerLimit = 16 + kickPower * 0.15;
        const powerSufficient = speed <= powerLimit;
        if (!powerSufficient) {
          const scale = powerLimit / speed;
          flight.vx *= scale; flight.vy *= scale; flight.vz *= scale;
        }
        Object.assign(W.ball, { state: 'air', holder: null, x: from.x, y: from.y, z: from.z,
          vx: flight.vx, vy: flight.vy, vz: flight.vz, k: flight.k, tumble: true });
        holder.hasBall = false;
        kicker.pose = POSE.KICK;
        W.event('field_goal_kick', { kicker_id: kicker.id, distance_yards: distanceYards,
          kick_power: kickPower, kick_accuracy: kickAccuracy, launch_speed_mps: speed,
          power_limit_mps: powerLimit });
        kickModel = { power_rating: kickPower, accuracy_rating: kickAccuracy, distance_yards: distanceYards,
          horizontal_sigma_meters: horizontalSigma, vertical_sigma_meters: verticalSigma,
          launch_speed_mps: speed, power_limit_mps: powerLimit, power_sufficient: powerSufficient };
      }
    }

    if (kickLaunched && W.ball.state === 'air' && W.ball.x >= goalpostX) {
      const span = W.ball.x - prior.x;
      const t = span > 1e-9 ? clamp((goalpostX - prior.x) / span, 0, 1) : 1;
      crossing = { x: goalpostX / YD, y: (prior.y + (W.ball.y - prior.y) * t) / YD,
        z: prior.z + (W.ball.z - prior.z) * t };
      const halfWidth = 2.82;
      const made = kickModel.power_sufficient
        && Math.abs(crossing.y * YD - ballY) <= halfWidth
        && crossing.z >= 3.05 + 0.11;
      resultName = made ? 'made' : 'missed';
      terminal = W.t;
      W.event(made ? 'field_goal_made' : 'field_goal_missed', { kicker_id: kicker.id,
        crossing, distance_yards: distanceYards, power_sufficient: kickModel.power_sufficient });
    }
    if (kickLaunched && W.ball.state === 'loose') {
      resultName = 'missed'; terminal = W.t;
      W.event('field_goal_missed', { kicker_id: kicker.id, ball_spot: { x: W.ball.x / YD, y: W.ball.y / YD },
        distance_yards: distanceYards, power_sufficient: kickModel.power_sufficient });
    }
    if (W.ball.y < 0 || W.ball.y > FIELD_W) {
      resultName = 'missed'; terminal = W.t;
      W.event('field_goal_missed', { kicker_id: kicker.id,
        ball_spot: { x: W.ball.x / YD, y: W.ball.y / YD }, distance_yards: distanceYards });
    }
    if (terminal == null && W.t >= nextFrame - 1e-9) {
      record(); nextFrame += 1 / REC_HZ;
    }
  }
  if (terminal == null) return { schema_version: 'gridiron.autonomous-special-teams.v1',
    status: 'failed', kind: cfg.kind, seed: cfg.seed,
    failure: { reason: 'field_goal_flight_time_cap', time_limit_seconds: 7 }, events: W.events,
    trajectory: { roster, frames: frames.map((frame) => Array.from(frame)), stride, t0: 0, hz: REC_HZ },
    diagnostics: { assignments_executed: assignments.size, expected_assignments: 22, outcome_inputs: [] } };

  if (frames.length === 0 || terminal - (frames.length - 1) / REC_HZ > 1e-6) record();
  W.event('whistle', { reason: blocked ? 'blocked_field_goal' : `field_goal_${resultName}`, terminal_t: terminal });
  const result = { result: resultName, possession_after: resultName === 'made' ? null : 'receiving_team',
    kick_spot_yardline_100: cfg.yardline_100, distance_yards: distanceYards,
    elapsed_seconds: terminal, clock_runoff_seconds: Math.ceil(terminal), scoring: resultName === 'made' ? 'field_goal' : null,
    out_of_bounds: false, returner_id: null, crossing };
  return { schema_version: 'gridiron.autonomous-special-teams.v1', status: 'complete', kind: cfg.kind,
    seed: cfg.seed, kicking_team: cfg.kicking_team, receiving_team: cfg.receiving_team, result,
    events: W.events, trajectory: { roster, frames: frames.map((frame) => Array.from(frame)), stride, t0: 0, hz: REC_HZ },
    diagnostics: { assignments_executed: assignments.size, expected_assignments: 22,
      decision_counts: Object.fromEntries(W.players.map((p) => [p.id, 1])), outcome_inputs: [],
      player_execution: W.players.map((p) => ({ player_id: p.id, assignment: assignments.get(p.id),
        top_speed_yards_per_second: p.topSpeed / YD, distance_yards: p.dist / YD })),
      kick_model: kickModel, outcome: resultName, blocked, provenance: 'generated snap, protection, kick flight, and goal geometry' } };
}
